import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
const x = JSON.parse(readFileSync(new URL('./ota-trusted-workflow-03d-observations.json', import.meta.url),'utf8'));
const doc = readFileSync(new URL('./OTA_TRUSTED_WORKFLOW_03D_OBSERVATIONS.md', import.meta.url),'utf8');
const hex = s => typeof s === 'string' && /^[a-f0-9]{40}$/.test(s);
test('observation only',()=>assert.equal(x.kind,'read_only_github_workflow_identity_observation'));
test('repository identity',()=>{assert.equal(x.repository,'SATananov/USGCorso');assert.equal(x.repositoryId,1436603966)});
test('workflow path canonical',()=>assert.equal(x.workflowPath,'.github/workflows/ota-preview-publish.yml'));
test('full immutable main commit',()=>assert.ok(hex(x.main.commit)));
test('full immutable candidate commit',()=>assert.ok(hex(x.candidate.commit)));
test('distinct git commits',()=>assert.notEqual(x.main.commit,x.candidate.commit));
test('git blob id recorded for main',()=>assert.ok(hex(x.main.gitBlobSha1)));
test('git blob id recorded for candidate',()=>assert.ok(hex(x.candidate.gitBlobSha1)));
test('blob IDs differ',()=>assert.notEqual(x.main.gitBlobSha1,x.candidate.gitBlobSha1));
test('main is registration only',()=>assert.equal(x.main.role,'dispatch_registration_only'));
test('candidate is untrusted',()=>assert.match(x.candidate.role,/untrusted/));
test('neither workflow approved',()=>{assert.equal(x.main.approval,false);assert.equal(x.candidate.approval,false)});
test('no fabricated main SHA-256',()=>assert.equal(x.main.fileSha256,null));
test('no fabricated candidate SHA-256',()=>assert.equal(x.candidate.fileSha256,null));
test('no approved trusted publisher',()=>assert.equal(x.trustedPublisher.selected,false));
test('no approved commit',()=>assert.equal(x.trustedPublisher.approvedWorkflowCommit,null));
test('no approved workflow SHA-256',()=>assert.equal(x.trustedPublisher.approvedWorkflowFileSha256,null));
test('attempt not proven',()=>assert.equal(x.trustedPublisher.artifactAttemptBindingVerified,false));
test('attestation not proven',()=>assert.equal(x.trustedPublisher.attestationVerified,false));
test('release denied',()=>assert.equal(x.trustedPublisher.releaseAuthorized,false));
test('contract emphasizes non-authorization',()=>assert.match(doc,/NOT A RELEASE GATE/));
test('contract requires independent SHA-256',()=>assert.match(doc,/SHA-256/));
test('contract denies candidate credential access',()=>assert.match(doc,/EXPO_TOKEN/));
test('contract preserves attempt binding requirement',()=>assert.match(doc,/artifact-to-`run_attempt` binding/));
test('no secret values in fixture',()=>assert.doesNotMatch(JSON.stringify(x),/EXPO_TOKEN|github_pat_|ghp_/));
